package by.bsuir.gateway; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import java.util.*;
@Component public class CurrentUser {public AuthPrincipal get(){Object p=SecurityContextHolder.getContext().getAuthentication()==null?null:SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(p instanceof AuthPrincipal a)return a;throw new org.springframework.security.authentication.AuthenticationCredentialsNotFoundException("Authentication is required");}public Map<String,Object> enrich(Map<String,Object> input){var value=new LinkedHashMap<String,Object>(input==null?Map.of():input);var user=get();value.put("currentUserId",user.userId());value.put("role",user.role());return value;}}
